"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[304],{69544:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"messaging","desc":"","lua_type":"any"},{"name":"onEnvelope","desc":"Called with `(envelope, source)` for each newly seen match.","lua_type":"(any, string) -> ()"},{"name":"fetch","desc":"Reads an envelope from the ledger by matchId, for non-inline messages.","lua_type":"(string) -> any"}],"returns":[],"function_type":"static","source":{"line":69,"path":"src/internal/Broadcaster.luau"}},{"name":"topicFor","desc":"The topic a given server listens on. With `topicShards` set, servers are\\nfolded into a fixed number of topics instead \u2014 a lever that exists in case\\ntopic cardinality ever becomes a constraint, and which nothing needs today.","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"serverId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string\\n"}],"function_type":"static","source":{"line":92,"path":"src/internal/Broadcaster.luau"}},{"name":"accept","desc":"Records a matchId and reports whether it is new. Bounded to\\n`Defaults.SEEN_CAPACITY` entries, evicted oldest-first, so a server that\\nlives for days does not accumulate them.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"},{"name":"matchId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":108,"path":"src/internal/Broadcaster.luau"}},{"name":"isHealthy","desc":"","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":126,"path":"src/internal/Broadcaster.luau"}},{"name":"markUnhealthy","desc":"Marks delivery as unreliable for `BROADCAST_UNHEALTHY_DURATION` seconds.\\nCalled on a failed publish, and when a poll finds a match that a doorbell\\nshould have delivered first.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[],"function_type":"static","source":{"line":140,"path":"src/internal/Broadcaster.luau"}},{"name":"start","desc":"Subscribes to this server\'s topic. Safe to call twice.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[],"function_type":"static","source":{"line":149,"path":"src/internal/Broadcaster.luau"}},{"name":"stop","desc":"","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[],"function_type":"static","source":{"line":161,"path":"src/internal/Broadcaster.luau"}},{"name":"announce","desc":"Publishes a finalized match to every other server holding one of its\\nmembers. Never called before the match is committed.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"},{"name":"envelope","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":198,"path":"src/internal/Broadcaster.luau"}},{"name":"pollInterval","desc":"How long a ticket should wait before its next poll, given how many polls it\\nhas already done. Doubles from `pollInterval`, capped at `pollIntervalMax`\\nwhile broadcasts look healthy and at the much tighter\\n`pollIntervalUnhealthy` while they do not.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"},{"name":"attempt","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":242,"path":"src/internal/Broadcaster.luau"}}],"properties":[],"types":[],"name":"Broadcaster","desc":"Cross-server delivery of finalized matches.\\n\\n**MemoryStore is the ledger; MessagingService is the doorbell.** A match is\\nwritten and flipped to `Ready` before any message is published, so the\\nmessage only ever says \\"go look\\" sooner than polling would have. Drop every\\nmessage and the system still works \u2014 it just gets slower, and it notices.\\n\\n### Addressing\\n\\nOne topic per server, `<namespace><version>:<serverId>`, and each instance\\nsubscribes to exactly one. A match publishes only to the distinct servers\\nholding its members, which is typically two to six.\\n\\nThe alternative \u2014 one shared topic every server filters \u2014 looks simpler and\\nscales far worse. Roblox\'s per-universe receive budget is `400 + 200 x\\nservers` per minute, and a shared topic spends `servers` of that on every\\nsingle match, which pins the whole experience at roughly 200 matches per\\nminute no matter how large it grows. Per-server topics spend a handful per\\nmatch regardless of fleet size.\\n\\n### Payload\\n\\nSmall envelopes ride along inside the message, saving the receiver a read.\\nLarger ones send just the matchId and the receiver fetches from the ledger.\\nEither way the message is advisory, so an envelope that arrives inline is\\nsafe to trust: it only exists because the commit already succeeded.\\n\\n### Health\\n\\nIf a publish fails, or a match is discovered by polling that a doorbell\\nshould have announced, the broadcaster marks itself unhealthy for a while.\\nTickets react by tightening their poll cap, so a MessagingService outage\\ncosts seconds of extra latency instead of minutes \u2014 and costs nothing at all\\nwhile things are working.","source":{"line":41,"path":"src/internal/Broadcaster.luau"}}')}}]);